const rows = $input.all();

// Calculate stats
const total = rows.length;
const pending = rows.filter(r => r.json['Status'] === 'Pending').length;
const booked = rows.filter(r => r.json['Status'] === 'Booked').length;
const optedOut = rows.filter(r => r.json['Status'] === 'Opted Out').length;
const replied = rows.filter(r => r.json['Status'] === 'Customer Replied').length;
const complete = rows.filter(r => r.json['Status'] === 'Follow-up Complete').length;

// Build table rows
const tableRows = rows.map(row => {
  const status = row.json['Status'] || '';
  const statusColors = {
    'Pending': '#FFA500',
    'Booked': '#00AA00',
    'Opted Out': '#FF0000',
    'Customer Replied': '#0000FF',
    'Follow-up Complete': '#888888'
  };
  const color = statusColors[status] || '#000000';

  return `
    <tr>
      <td>${row.json['Estimate ID'] || ''}</td>
      <td>${row.json['Customer Name'] || ''}</td>
      <td>${row.json['Email'] || ''}</td>
      <td>${row.json['Service Type'] || ''}</td>
      <td>${row.json['Estimate Amount'] || ''}</td>
      <td>${row.json['Estimate Date'] || ''}</td>
      <td><span style="color:${color};font-weight:bold">${status}</span></td>
      <td>${row.json['Follow-up Count'] || '0'}</td>
      <td>${row.json['Next Follow-up Date'] || ''}</td>
    </tr>
  `;
}).join('');

// Build full HTML page
const html = `
<!DOCTYPE html>
<html>
<head>
  <title>Cleaning Business Dashboard</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; background: #f5f5f5; }
    h1 { color: #333; }
    .stats { display: flex; gap: 20px; flex-wrap: wrap; margin-bottom: 30px; }
    .card {
      background: white;
      padding: 20px 30px;
      border-radius: 10px;
      box-shadow: 0 2px 5px rgba(0,0,0,0.1);
      text-align: center;
      min-width: 120px;
    }
    .card h2 { margin: 0; font-size: 40px; }
    .card p { margin: 5px 0 0; color: #666; font-size: 14px; }
    .total h2 { color: #333; }
    .pending h2 { color: #FFA500; }
    .booked h2 { color: #00AA00; }
    .opted h2 { color: #FF0000; }
    .replied h2 { color: #0000FF; }
    .complete h2 { color: #888888; }
    table {
      width: 100%;
      border-collapse: collapse;
      background: white;
      border-radius: 10px;
      overflow: hidden;
      box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    }
    th {
      background: #4CAF50;
      color: white;
      padding: 12px;
      text-align: left;
      font-size: 13px;
    }
    td { padding: 10px 12px; border-bottom: 1px solid #eee; font-size: 13px; }
    tr:hover { background: #f9f9f9; }
    tr:last-child td { border-bottom: none; }
    .refresh {
      float: right;
      background: #4CAF50;
      color: white;
      border: none;
      padding: 10px 20px;
      border-radius: 5px;
      cursor: pointer;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <h1>🧹 Cleaning Business Dashboard</h1>
  <button class="refresh" onclick="location.reload()">🔄 Refresh</button>

  <div class="stats">
    <div class="card total"><h2>${total}</h2><p>Total Estimates</p></div>
    <div class="card pending"><h2>${pending}</h2><p>Pending</p></div>
    <div class="card booked"><h2>${booked}</h2><p>Booked</p></div>
    <div class="card opted"><h2>${optedOut}</h2><p>Opted Out</p></div>
    <div class="card replied"><h2>${replied}</h2><p>Customer Replied</p></div>
    <div class="card complete"><h2>${complete}</h2><p>Follow-up Complete</p></div>
  </div>

  <table>
    <thead>
      <tr>
        <th>Estimate ID</th>
        <th>Customer Name</th>
        <th>Email</th>
        <th>Service Type</th>
        <th>Amount</th>
        <th>Date</th>
        <th>Status</th>
        <th>Follow-ups</th>
        <th>Next Follow-up</th>
      </tr>
    </thead>
    <tbody>
      ${tableRows}
    </tbody>
  </table>
</body>
</html>
`;

return [{ json: { html: html }}];
